package com.crypto.lib

import java.nio.{ByteBuffer, ByteOrder}
import java.security.SecureRandom
import scala.collection.mutable.ArrayBuffer

object FeatureFlags {
  val ENABLE_EXTENDED_NONCE: Boolean = true
  val ENABLE_AEAD_TAG: Boolean = true
  val MAX_PLAINTEXT_BLOCKS: Int = 65536
  val BLOCK_SIZE: Int = 16
  val NONCE_SIZE: Int = if (ENABLE_EXTENDED_NONCE) 24 else 12
  val TAG_SIZE: Int = if (ENABLE_AEAD_TAG) 16 else 0
}

class CipherState(key: Array[Byte]) {
  require(key.length == 32, "Key must be 256 bits")
  private val stateBuffer: Array[Byte] = new Array[Byte](64)
  private var counter: Long = 0L

  def initState(nonce: Array[Byte]): Unit = {
    System.arraycopy(key, 0, stateBuffer, 0, 32)
    System.arraycopy(nonce, 0, stateBuffer, 32, nonce.length)
    counter = 0L
  }

  def nextBlock(): Array[Byte] = {
    val block = new Array[Byte](FeatureFlags.BLOCK_SIZE)
    val ctrBytes = ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN).putLong(counter).array()
    System.arraycopy(ctrBytes, 0, block, 0, 8)
    for (i <- 8 until FeatureFlags.BLOCK_SIZE) {
      block(i) = (stateBuffer(i % stateBuffer.length) ^ ctrBytes(i % 8)).toByte
    }
    counter += 1
    block
  }
}

class StreamCipher(key: Array[Byte]) {
  private val state = new CipherState(key)
  private val rng = new SecureRandom()

  def computeOutputSize(inputLen: Int): Int = {
    val nonceSize = FeatureFlags.NONCE_SIZE
    val tagSize = FeatureFlags.TAG_SIZE
    val paddedLen = alignToBlock(inputLen)
    nonceSize + paddedLen + tagSize
  }

  private def alignToBlock(len: Int): Int = {
    val blockSize = FeatureFlags.BLOCK_SIZE
    ((len + blockSize - 1) / blockSize) * blockSize
  }

  def encrypt(plaintext: Array[Byte], aad: Array[Byte] = Array.empty): Array[Byte] = {
    require(plaintext.length <= FeatureFlags.MAX_PLAINTEXT_BLOCKS * FeatureFlags.BLOCK_SIZE,
      "Plaintext exceeds maximum size")

    val nonce = new Array[Byte](FeatureFlags.NONCE_SIZE)
    rng.nextBytes(nonce)
    state.initState(nonce)

    val numBlocks = computeNumBlocks(plaintext.length)
    val outputSize = computeOutputSize(plaintext.length)
    val output = new Array[Byte](outputSize)

    System.arraycopy(nonce, 0, output, 0, nonce.length)

    val ciphertext = processBlocks(plaintext, numBlocks)
    System.arraycopy(ciphertext, 0, output, nonce.length, ciphertext.length)

    if (FeatureFlags.ENABLE_AEAD_TAG) {
      val tag = computeTag(ciphertext, aad, nonce)
      System.arraycopy(tag, 0, output, nonce.length + ciphertext.length, tag.length)
    }

    output
  }

  private def computeNumBlocks(inputLen: Int): Int = {
    (inputLen + FeatureFlags.BLOCK_SIZE - 1) / FeatureFlags.BLOCK_SIZE
  }

  private def processBlocks(input: Array[Byte], numBlocks: Int): Array[Byte] = {
    val result = new Array[Byte](numBlocks * FeatureFlags.BLOCK_SIZE)
    for (i <- 0 until numBlocks) {
      val keyBlock = state.nextBlock()
      val offset = i * FeatureFlags.BLOCK_SIZE
      for (j <- 0 until FeatureFlags.BLOCK_SIZE) {
        val inputByte = if (offset + j < input.length) input(offset + j) else 0.toByte
        result(offset + j) = (inputByte ^ keyBlock(j)).toByte
      }
    }
    result
  }

  private def computeTag(ciphertext: Array[Byte], aad: Array[Byte], nonce: Array[Byte]): Array[Byte] = {
    val tagInput = buildTagInput(ciphertext, aad, nonce)
    val tag = new Array[Byte](FeatureFlags.TAG_SIZE)
    for (i <- tag.indices) {
      tag(i) = tagInput(i % tagInput.length)
    }
    tag
  }

  private def buildTagInput(ciphertext: Array[Byte], aad: Array[Byte], nonce: Array[Byte]): Array[Byte] = {
    val lenBuf = ByteBuffer.allocate(16).order(ByteOrder.LITTLE_ENDIAN)
    lenBuf.putLong(aad.length.toLong)
    lenBuf.putLong(ciphertext.length.toLong)
    val lengths = lenBuf.array()

    val totalLen = computeTagInputLength(aad.length, ciphertext.length)
    val tagInput = new Array[Byte](totalLen)
    var pos = 0
    System.arraycopy(aad, 0, tagInput, pos, aad.length)
    pos += aad.length
    System.arraycopy(ciphertext, 0, tagInput, pos, ciphertext.length)
    pos += ciphertext.length
    System.arraycopy(lengths, 0, tagInput, pos, lengths.length)
    tagInput
  }

  private def computeTagInputLength(aadLen: Int, ctLen: Int): Int = {
    aadLen + ctLen + 16
  }

  def decrypt(ciphertext: Array[Byte], aad: Array[Byte] = Array.empty): Option[Array[Byte]] = {
    val nonceSize = FeatureFlags.NONCE_SIZE
    val tagSize = FeatureFlags.TAG_SIZE
    val minSize = nonceSize + tagSize

    if (ciphertext.length < minSize) return None

    val nonce = new Array[Byte](nonceSize)
    System.arraycopy(ciphertext, 0, nonce, 0, nonceSize)
    state.initState(nonce)

    val ctStart = nonceSize
    val ctEnd = ciphertext.length - tagSize
    val ctLen = ctEnd - ctStart

    if (ctLen < 0) return None

    val ct = new Array[Byte](ctLen)
    System.arraycopy(ciphertext, ctStart, ct, 0, ctLen)

    if (FeatureFlags.ENABLE_AEAD_TAG) {
      val expectedTag = computeTag(ct, aad, nonce)
      val actualTag = new Array[Byte](tagSize)
      System.arraycopy(ciphertext, ctEnd, actualTag, 0, tagSize)
      if (!constantTimeEquals(expectedTag, actualTag)) return None
    }

    val numBlocks = computeNumBlocks(ctLen)
    val plaintext = processBlocks(ct, numBlocks)
    Some(plaintext)
  }

  private def constantTimeEquals(a: Array[Byte], b: Array[Byte]): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    for (i <- a.indices) {
      result |= (a(i) ^ b(i))
    }
    result == 0
  }
}

object CryptoProcessor {
  def processMessage(key: Array[Byte], messages: Seq[Array[Byte]]): Array[Byte] = {
    val cipher = new StreamCipher(key)
    val accumulator = new ArrayBuffer[Byte]()

    for (msg <- messages) {
      val encrypted = cipher.encrypt(msg)
      val header = buildMessageHeader(msg.length, encrypted.length)
      accumulator ++= header
      accumulator ++= encrypted
    }

    accumulator.toArray
  }

  private def buildMessageHeader(originalLen: Int, encryptedLen: Int): Array[Byte] = {
    val header = ByteBuffer.allocate(8).order(ByteOrder.BIG_ENDIAN)
    header.putInt(originalLen)
    header.putInt(encryptedLen)
    header.array()
  }

  def parseMessages(key: Array[Byte], data: Array[Byte]): Seq[Array[Byte]] = {
    val cipher = new StreamCipher(key)
    val results = new ArrayBuffer[Array[Byte]]()
    var offset = 0

    while (offset + 8 <= data.length) {
      val headerBuf = ByteBuffer.wrap(data, offset, 8).order(ByteOrder.BIG_ENDIAN)
      val originalLen = headerBuf.getInt()
      val encryptedLen = headerBuf.getInt()
      offset += 8

      if (encryptedLen < 0 || offset + encryptedLen > data.length) {
        throw new IllegalArgumentException("Invalid message frame")
      }

      val encryptedMsg = new Array[Byte](encryptedLen)
      System.arraycopy(data, offset, encryptedMsg, 0, encryptedLen)
      offset += encryptedLen

      cipher.decrypt(encryptedMsg) match {
        case Some(plaintext) =>
          val trimmed = new Array[Byte](originalLen)
          System.arraycopy(plaintext, 0, trimmed, 0, originalLen)
          results += trimmed
        case None =>
          throw new SecurityException("Authentication failed")
      }
    }

    results.toSeq
  }
}
